import logging

import torch
import triton
import triton.language as tl

from flag_gems.ops._pad_enum import _pad_enum as _pad_enum_generic
from flag_gems.runtime import torch_device_fn

_MAX_GRID_X = 65535  # device grid-dimension limit (Ascend coreDim <= 65535)
# Persistent grid width.  Starting a block costs about a microsecond of setup on
# this backend -- as much as a narrow row costs to move -- so each program takes a
# contiguous run of work items and streams through them.  A few programs per
# vector core (40 on 910B3/B4) leaves enough concurrency for the memory pipeline.
_NPROG = 160
# The pad-only pass walks one row at a time, and a row costs the same ~7 ns
# whether it is 64 or 4096 elements wide (two small stores plus a scalar loop
# iteration), whereas one flat pass over the output costs ~2.5 ps per element.
# Padding a row narrower than about 2800 elements therefore costs more than
# simply writing the whole output and letting the copy overwrite the interior.
_PAD_FILL_MIN_LAST = 2816

logger = logging.getLogger(__name__)


def _tile_params(n):
    """``(block, tiles, masked)`` for a contiguous run of ``n`` elements.

    A block that fits inside the run is used unmasked, and the last tile is
    shifted back so that it overlaps its predecessor.  Re-touching those
    elements is harmless for both passes here (a constant fill and an
    idempotent copy), and it keeps every lane of every access inside the
    tensor: a masked load issues its full vector on this backend, so a masked
    lane past the end of the allocation faults on a large tensor.
    """
    if n >= 64:
        block = min(8192, 1 << (n.bit_length() - 1))
        return block, triton.cdiv(n, block), False
    return triton.next_power_of_2(n), 1, True


@triton.jit
def _pad_fill_pads_kernel(
    out_ptr,
    num_rows,
    value,
    in_shape: tl.constexpr,
    out_shape: tl.constexpr,
    out_stride: tl.constexpr,
    pad_left: tl.constexpr,
    NDIM: tl.constexpr,
    IN_LAST: tl.constexpr,
    OUT_LAST: tl.constexpr,
    PAD_L: tl.constexpr,
    PAD_R: tl.constexpr,
    LP_BLOCK: tl.constexpr,
    RP_BLOCK: tl.constexpr,
    ROW_BLOCK: tl.constexpr,
    ROW_TILES: tl.constexpr,
    ROW_MASKED: tl.constexpr,
    WIDE: tl.constexpr,
):
    """Write ``value`` into the padding region only.

    The output is walked one row (one combination of the leading coordinates)
    at a time.  A row whose leading coordinates fall in a pad band is padding
    from end to end; every other row only needs its two ends along the
    innermost axis.  Filling just those elements -- a couple of percent of the
    tensor for a typical pad -- leaves the interior to ``_pad_copy_kernel``,
    which is a third less memory traffic than filling the whole output first.
    """
    pid = tl.program_id(0)
    lp = tl.arange(0, LP_BLOCK)
    rp = tl.arange(0, RP_BLOCK)
    rl = tl.arange(0, ROW_BLOCK)
    row_fill = tl.full((ROW_BLOCK,), value, dtype=out_ptr.dtype.element_ty)
    lp_fill = tl.full((LP_BLOCK,), value, dtype=out_ptr.dtype.element_ty)
    rp_fill = tl.full((RP_BLOCK,), value, dtype=out_ptr.dtype.element_ty)

    per = tl.cdiv(num_rows, tl.num_programs(0))
    row = pid * per
    stop = tl.minimum(row + per, num_rows)
    while row < stop:
        if WIDE:
            row_flat = row.to(tl.int64) * OUT_LAST
        else:
            row_flat = row.to(tl.int32) * OUT_LAST
        # Scalar decomposition of the row index over the leading dimensions.
        row_oob = 0
        for d in tl.static_range(NDIM - 1):
            c = (row_flat // out_stride[d]) % out_shape[d]
            j = c - pad_left[d]
            row_oob = row_oob + ((j < 0) | (j >= in_shape[d])).to(tl.int32)

        if row_oob != 0:
            for t in tl.range(ROW_TILES):
                if ROW_MASKED:
                    tl.store(out_ptr + row_flat + rl, row_fill, mask=rl < OUT_LAST)
                else:
                    base = tl.minimum(t * ROW_BLOCK, OUT_LAST - ROW_BLOCK)
                    tl.store(out_ptr + row_flat + base + rl, row_fill)
        else:
            if PAD_L > 0:
                tl.store(out_ptr + row_flat + lp, lp_fill, mask=lp < PAD_L)
            if PAD_R > 0:
                tl.store(
                    out_ptr + row_flat + (PAD_L + IN_LAST) + rp,
                    rp_fill,
                    mask=rp < PAD_R,
                )
        row += 1


@triton.jit
def _pad_fill_flat_kernel(out_ptr, numel, value, BLOCK: tl.constexpr):
    """Write ``value`` over the whole output.

    Used for narrow rows, where a per-row pad pass costs more than the extra
    write: a row only a few hundred elements wide pays a full scalar loop
    iteration (and its integer division) for every few bytes it fills.
    """
    pid = tl.program_id(0)
    lanes = tl.arange(0, BLOCK)
    fill = tl.full((BLOCK,), value, dtype=out_ptr.dtype.element_ty)
    per = tl.cdiv(numel, tl.num_programs(0) * BLOCK) * BLOCK
    base = pid * per
    stop = tl.minimum(base + per, numel)
    while base < stop:
        offs = base + lanes
        tl.store(out_ptr + offs, fill, mask=offs < numel)
        base += BLOCK


@triton.jit
def _pad_copy_kernel(
    x_ptr,
    out_ptr,
    num_rows,
    in_shape: tl.constexpr,
    out_stride: tl.constexpr,
    in_row_stride: tl.constexpr,
    pad_left: tl.constexpr,
    NDIM: tl.constexpr,
    IN_LAST: tl.constexpr,
    PAD_L: tl.constexpr,
    BLOCK: tl.constexpr,
    TILES: tl.constexpr,
    ROWS: tl.constexpr,
    MASKED: tl.constexpr,
    WIDE: tl.constexpr,
):
    """Copy each input row into its slot in the padded output.

    Rows are enumerated in input order, so the source of a row is simply
    ``row * IN_LAST`` (the input is contiguous) while its destination is the
    sum of its shifted coordinates -- resolved with scalar arithmetic, never
    per element.  ``ROWS`` rows share one tile: the inner axis is contiguous on
    both sides, so a narrow row still forms a transfer of tens of kilobytes,
    which is what the memory engine needs to hide its latency.  Both sides of
    every transfer are entirely inside the tensor, so no lane mask is needed
    and no lane can address past the allocation.
    """
    pid = tl.program_id(0)
    rl = tl.arange(0, ROWS)
    lanes = tl.arange(0, BLOCK)
    total = tl.cdiv(num_rows, ROWS) * TILES
    per = tl.cdiv(total, tl.num_programs(0))
    unit = pid * per
    stop = tl.minimum(unit + per, total)
    while unit < stop:
        group = unit // TILES
        tile = unit % TILES
        rows = group * ROWS + rl
        ok = rows < num_rows
        # Clamping the row index keeps the (unmasked) load in bounds.
        r = tl.minimum(rows, num_rows - 1)
        if WIDE:
            r_i = r.to(tl.int64)
        else:
            r_i = r.to(tl.int32)
        in_base = r_i * IN_LAST
        out_base = PAD_L + r_i * 0
        for d in tl.static_range(NDIM - 1):
            c = (r_i // in_row_stride[d]) % in_shape[d]
            out_base += (c + pad_left[d]) * out_stride[d]

        if MASKED:
            # Only an innermost axis shorter than one lane vector lands here:
            # clamping the index keeps the load in bounds, and only the tail
            # lanes of the store are masked off.
            idx = tl.where(lanes < IN_LAST, lanes, 0)
            val = tl.load(x_ptr + in_base[:, None] + idx[None, :])
            tl.store(
                out_ptr + out_base[:, None] + lanes[None, :],
                val,
                mask=(lanes < IN_LAST)[None, :] & ok[:, None],
            )
        else:
            off = tl.minimum(tile * BLOCK, IN_LAST - BLOCK) + lanes
            val = tl.load(x_ptr + in_base[:, None] + off[None, :])
            tl.store(out_ptr + out_base[:, None] + off[None, :], val, mask=ok[:, None])
        unit += 1


@triton.jit
def _pad_enum_kernel(
    x_ptr,
    out_ptr,
    num_rows,
    value,
    in_shape: tl.constexpr,
    out_shape: tl.constexpr,
    out_stride: tl.constexpr,
    in_stride: tl.constexpr,
    pad_left: tl.constexpr,
    NDIM: tl.constexpr,
    MODE: tl.constexpr,
    OUT_LAST: tl.constexpr,
    TILES_PER_ROW: tl.constexpr,
    BLOCK: tl.constexpr,
):
    """Fill a padded tensor, one contiguous row-tile at a time.

    A flat per-element kernel has to decompose every output offset into
    per-dimension coordinates, i.e. do ``NDIM`` integer divisions per element.
    Integer division is very slow on some accelerators (Ascend has no hardware
    divide), so instead each program owns one tile of a row: the leading
    coordinates are resolved once per program (scalar arithmetic) and only the
    innermost axis is handled as a vector.  This is the strided-source path used
    by the reflect/replicate/circular modes; its coordinates are clamped into
    the input, so every lane of the gather stays in bounds.
    """
    pid = tl.program_id(0)
    step = tl.num_programs(0)
    total = num_rows * TILES_PER_ROW
    lanes = tl.arange(0, BLOCK)

    tile_id = pid
    while tile_id < total:
        row = tile_id // TILES_PER_ROW
        tile = tile_id % TILES_PER_ROW

        # Scalar decomposition of the row index over the leading dimensions.
        row_flat = row * OUT_LAST
        base_in = 0
        for d in tl.static_range(NDIM - 1):
            c = (row_flat // out_stride[d]) % out_shape[d]
            j = c - pad_left[d]
            if MODE == 1:  # replicate
                in_coord = tl.maximum(0, tl.minimum(j, in_shape[d] - 1))
            elif MODE == 2:  # circular
                r = j % in_shape[d]
                in_coord = tl.where(r < 0, r + in_shape[d], r)
            else:  # MODE == 0, reflect (reflect_101)
                if in_shape[d] == 1:
                    in_coord = 0
                else:
                    m = j % (2 * (in_shape[d] - 1))
                    m = tl.where(m < 0, m + 2 * (in_shape[d] - 1), m)
                    in_coord = tl.where(m >= in_shape[d], 2 * (in_shape[d] - 1) - m, m)
            base_in += in_coord * in_stride[d]

        offs = tile * BLOCK + lanes
        mask = offs < OUT_LAST
        j = offs - pad_left[NDIM - 1]

        if MODE == 1:  # replicate
            last_coord = tl.maximum(0, tl.minimum(j, in_shape[NDIM - 1] - 1))
        elif MODE == 2:  # circular
            r = j % in_shape[NDIM - 1]
            last_coord = tl.where(r < 0, r + in_shape[NDIM - 1], r)
        else:  # reflect (reflect_101)
            if in_shape[NDIM - 1] == 1:
                last_coord = tl.zeros((BLOCK,), dtype=tl.int32)
            else:
                m = j % (2 * (in_shape[NDIM - 1] - 1))
                m = tl.where(m < 0, m + 2 * (in_shape[NDIM - 1] - 1), m)
                last_coord = tl.where(
                    m >= in_shape[NDIM - 1],
                    2 * (in_shape[NDIM - 1] - 1) - m,
                    m,
                )
        result = tl.load(
            x_ptr + base_in + last_coord * in_stride[NDIM - 1],
            mask=mask,
            other=0.0,
        )

        tl.store(out_ptr + row * OUT_LAST + offs, result, mask=mask)
        tile_id += step


# aten padding_mode enum -> readable name (see aten/src/ATen/native/PadNd.cpp)
_MODE_REFLECT = 0
_MODE_REPLICATE = 1
_MODE_CIRCULAR = 2
_MODE_CONSTANT = 3


def _row_strides(shape):
    """Row-major strides of ``shape[:-1]``, used to decode an input row index."""
    strides = [1] * len(shape)
    acc = 1
    for d in range(len(shape) - 2, -1, -1):
        strides[d] = acc
        acc *= shape[d]
    return tuple(strides)


def _pad_enum(self, pad, mode, value=None):
    logger.debug("GEMS _PAD_ENUM")

    assert len(pad) % 2 == 0, "Padding length must be divisible by 2"
    ndim = self.dim()
    k = len(pad) // 2
    assert k <= ndim, "Padding length too large"

    inp = self.contiguous()
    in_shape = list(inp.shape)
    out_shape = list(in_shape)
    pad_left = [0] * ndim

    if min(pad) < 0:
        # A negative pad crops, so a coordinate can start before zero on the
        # output side and the row tiles below would form negative offsets.  The
        # flat generic kernel folds the coordinates instead.
        return _pad_enum_generic(self, pad, mode, value)
    for i in range(k):
        dim = ndim - 1 - i
        left = pad[2 * i]
        right = pad[2 * i + 1]
        out_shape[dim] = in_shape[dim] + left + right
        pad_left[dim] = left

    if mode == _MODE_REFLECT:
        for i in range(k):
            dim = ndim - 1 - i
            assert (
                pad[2 * i] < in_shape[dim] and pad[2 * i + 1] < in_shape[dim]
            ), "Padding size should be less than the corresponding input dimension"
    elif mode == _MODE_CIRCULAR:
        for i in range(k):
            dim = ndim - 1 - i
            assert (
                pad[2 * i] <= in_shape[dim] and pad[2 * i + 1] <= in_shape[dim]
            ), "Padding value causes wrapping around more than once"

    out = torch.empty(out_shape, dtype=inp.dtype, device=inp.device)

    numel_out = out.numel()
    v = float(value) if (mode == _MODE_CONSTANT and value is not None) else 0.0

    if numel_out == 0:
        return out

    out_last = out_shape[-1]
    num_out_rows = numel_out // out_last
    # Offsets are int32 unless the tensor needs wider ones.
    wide = max(numel_out, inp.numel()) > 2**31 - 1

    if mode == _MODE_CONSTANT:
        # Two mask-free passes over contiguous address ranges: write the
        # padding, then copy the input rows into their slots.
        in_last = in_shape[-1]
        pad_l = pad_left[-1]
        pad_r = out_last - pad_l - in_last
        block, tiles, masked = _tile_params(in_last)
        rows = max(1, min(64, 8192 // block))
        with torch_device_fn.device(inp.device):
            if out_shape != in_shape:
                if out_last < _PAD_FILL_MIN_LAST:
                    # Narrow rows: one flat pass beats per-row padding.
                    _pad_fill_flat_kernel.run(
                        out,
                        numel_out,
                        v,
                        BLOCK=8192,
                        grid=(min(triton.cdiv(numel_out, 8192), _NPROG),),
                        warmup=False,
                    )
                else:
                    lp_block = triton.next_power_of_2(max(1, pad_l))
                    rp_block = triton.next_power_of_2(max(1, pad_r))
                    row_block, row_tiles, row_masked = _tile_params(out_last)
                    _pad_fill_pads_kernel.run(
                        out,
                        num_out_rows,
                        v,
                        in_shape=tuple(in_shape),
                        out_shape=tuple(out_shape),
                        out_stride=tuple(out.stride()),
                        pad_left=tuple(pad_left),
                        NDIM=ndim,
                        IN_LAST=in_last,
                        OUT_LAST=out_last,
                        PAD_L=pad_l,
                        PAD_R=pad_r,
                        LP_BLOCK=lp_block,
                        RP_BLOCK=rp_block,
                        ROW_BLOCK=row_block,
                        ROW_TILES=row_tiles,
                        ROW_MASKED=row_masked,
                        WIDE=wide,
                        grid=(min(num_out_rows, _NPROG),),
                        warmup=False,
                    )

            num_in_rows = inp.numel() // in_last if inp.numel() else 0
            total = triton.cdiv(num_in_rows, rows) * tiles
            if total == 0:
                # Empty input: the output is padding end to end and the fill
                # pass above already wrote it.
                return out
            _pad_copy_kernel.run(
                inp,
                out,
                num_in_rows,
                in_shape=tuple(in_shape),
                out_stride=tuple(out.stride()),
                in_row_stride=_row_strides(in_shape),
                pad_left=tuple(pad_left),
                NDIM=ndim,
                IN_LAST=in_last,
                PAD_L=pad_l,
                BLOCK=block,
                TILES=tiles,
                ROWS=rows,
                MASKED=masked,
                WIDE=wide,
                grid=(min(total, _NPROG),),
                warmup=False,
            )
        return out

    # reflect / replicate / circular: the source is strided, so gather row by
    # row with the coordinates folded back into the input.
    block = min(8192, max(64, triton.next_power_of_2(out_last)))
    tiles_per_row = max(1, triton.cdiv(out_last, block))
    grid = (min(num_out_rows * tiles_per_row, _MAX_GRID_X),)
    with torch_device_fn.device(inp.device):
        _pad_enum_kernel.run(
            inp,
            out,
            num_out_rows,
            v,
            in_shape=tuple(in_shape),
            out_shape=tuple(out_shape),
            out_stride=tuple(out.stride()),
            in_stride=tuple(inp.stride()),
            pad_left=tuple(pad_left),
            NDIM=ndim,
            MODE=int(mode),
            OUT_LAST=out_last,
            TILES_PER_ROW=tiles_per_row,
            BLOCK=block,
            grid=grid,
            warmup=False,
        )
    return out
